import{_ as a,o as r,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2016Q3 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2016Q3 Ceph社区季度进展报告","date":"2016-09-01T00:00:00.000Z","updated":"2016-09-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2016/2016Q3_Ceph社区季度总结.md","filePath":"posts/2016/2016Q3_Ceph社区季度总结.md","lastUpdated":1780460162000}'),t={name:"posts/2016/2016Q3_Ceph社区季度总结.md"};function h(i,e,n,s,p,_){return r(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="ceph-社区季度进展报告-—-2016-q3" tabindex="-1">Ceph 社区季度进展报告 — 2016 Q3 <a class="header-anchor" href="#ceph-社区季度进展报告-—-2016-q3" aria-label="Permalink to &quot;Ceph 社区季度进展报告 — 2016 Q3&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度开发者讨论高度集中在以下几个反复出现的技术方向：</p><p><strong>存储引擎与序列化优化</strong> BlueStore 的 onode 序列化改进是本季度的核心议题之一，详见 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03_-_-Ceph_Developer_Monthly</a>)。编码/解码框架的 CPU 开销优化贯穿整个季度讨论。</p><p><strong>RBD 功能扩展</strong> RBD 镜像横向扩展、客户端持久缓存、快照与一致性组三个方向同步推进，是本季度 RBD 子系统的主要投入方向，详见 <a href="./2016-AUG-03_-_Ceph_Developer_Monthly.html">2016-AUG-03_-_-_Ceph_Developer_Monthly</a> 和 <a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">2016-SEP-07_-_-_Ceph_Developer_Monthly</a>)。</p><p><strong>Kraken / Luminous 版本准备</strong> 多个议题（Manager、PG 状态迁移、EC 覆写）均以 Kraken 和 Luminous 版本为交付目标，版本规划压力明显。</p><p><strong>CI/CD 基础设施现代化</strong> 构建和发布流程的统一化改造是本季度基础设施层面的重点，详见 <a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">2016-AUG-25_--<em>Ceph_Tech_Talk</em>-_Unified_CI</a>)。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="bluestore-—-onode-序列化改进" tabindex="-1">BlueStore — onode 序列化改进 <a class="header-anchor" href="#bluestore-—-onode-序列化改进" aria-label="Permalink to &quot;BlueStore — onode 序列化改进&quot;">​</a></h3><p>Alan Samuels 在 <a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">8月开发者月会</a>) 中介绍了新的编码/解码框架：</p><ul><li>通过优化缓冲区操作和迭代器减少代码层级</li><li>引入标志位标识常见优化路径（如无空洞、单物理扩展）</li><li>减少物理扩展引用的序列化冗余，降低存储空间占用</li></ul><h3 id="cephfs-—-mantle-元数据负载均衡器" tabindex="-1">CephFS — Mantle 元数据负载均衡器 <a class="header-anchor" href="#cephfs-—-mantle-元数据负载均衡器" aria-label="Permalink to &quot;CephFS — Mantle 元数据负载均衡器&quot;">​</a></h3><p>Michael Silla 提出 Mantle 设计，通过 Lua 脚本注入控制 MDS 负载均衡策略，将策略与机制解耦。目前处于实验阶段，设计文档已发布至 Etherpad 供社区讨论。</p><h3 id="rbd-镜像横向扩展-三阶段方案" tabindex="-1">RBD 镜像横向扩展（三阶段方案） <a class="header-anchor" href="#rbd-镜像横向扩展-三阶段方案" aria-label="Permalink to &quot;RBD 镜像横向扩展（三阶段方案）&quot;">​</a></h3><p>Jason 提出分阶段实现路径：</p><ol><li>活动/被动故障转移（锁机制）</li><li>每图像横向扩展（RPC 消息分配）</li><li>热点能力扩展（指标驱动负载均衡）</li></ol><h3 id="rbd-客户端持久缓存" tabindex="-1">RBD 客户端持久缓存 <a class="header-anchor" href="#rbd-客户端持久缓存" aria-label="Permalink to &quot;RBD 客户端持久缓存&quot;">​</a></h3><p>支持读写数据本地缓存，克隆镜像可共享读缓存，底层使用稀疏文件或 BlueStore 实例，由缓存管理器负责槽位分配与垃圾回收。</p><h3 id="rbd-快照与一致性组" tabindex="-1">RBD 快照与一致性组 <a class="header-anchor" href="#rbd-快照与一致性组" aria-label="Permalink to &quot;RBD 快照与一致性组&quot;">​</a></h3><p><a href="./2016-SEP-07_-_Ceph_Developer_Monthly.html">9月开发者月会</a> 中 Sage 提出在快照设计中引入&quot;快照类型&quot;字段，支持用户快照与一致性组快照并行创建，并新增 <code>get_snapshot_id</code>、<code>get_image_id</code> 等辅助接口。</p><h3 id="ec-覆写-erasure-code-overwrites" tabindex="-1">EC 覆写（Erasure Code Overwrites） <a class="header-anchor" href="#ec-覆写-erasure-code-overwrites" aria-label="Permalink to &quot;EC 覆写（Erasure Code Overwrites）&quot;">​</a></h3><p>持久化缺失集合、缓存和哈希基础设施的改造工作持续推进，代码重构同步进行以提升可维护性。</p><h3 id="ddo-数据去重" tabindex="-1">DDO（数据去重） <a class="header-anchor" href="#ddo-数据去重" aria-label="Permalink to &quot;DDO（数据去重）&quot;">​</a></h3><p>Python 原型已完成，计划重写为 C++，支持内容地址对象存储与去重功能。</p><h3 id="simd-指令集检测" tabindex="-1">SIMD 指令集检测 <a class="header-anchor" href="#simd-指令集检测" aria-label="Permalink to &quot;SIMD 指令集检测&quot;">​</a></h3><p>Basam 提出在 EC 库中实现运行时 SIMD 指令集检测，以支持不同处理器架构的性能优化，详见 <a href="./2016-SEP-07_-_Ceph_Developer_Monthly.html">2016-SEP-07_-_-_Ceph_Developer_Monthly</a>。</p><h3 id="scrub-接口改进" tabindex="-1">Scrub 接口改进 <a class="header-anchor" href="#scrub-接口改进" aria-label="Permalink to &quot;Scrub 接口改进&quot;">​</a></h3><p>通过逐分片对象信息比对提升损坏检测精度，新增 JSON 输出格式，便于自动化脚本处理。</p><h3 id="kerberos-认证" tabindex="-1">Kerberos 认证 <a class="header-anchor" href="#kerberos-认证" aria-label="Permalink to &quot;Kerberos 认证&quot;">​</a></h3><p>讨论了定义新认证类型 <code>Kerberos 5</code>、直接对接 libkrb5、在 Monitor 中实现身份映射的方案，以及&quot;混合令牌&quot;机制。</p><h3 id="openattic-与-ceph-集成" tabindex="-1">OpenATTIC 与 Ceph 集成 <a class="header-anchor" href="#openattic-与-ceph-集成" aria-label="Permalink to &quot;OpenATTIC 与 Ceph 集成&quot;">​</a></h3><p><a href="/VideoSummary/posts/2016/2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATTIC.html">6月 Tech Talk</a>) 中介绍了 OpenATTIC 通过 Librados 和 LibRBD API 管理 Ceph 集群，集成 Nagios + RDtool 监控，并使用 Saltstack 实现远程节点自动化管理。</p><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><p><strong>Manager 组件引入</strong> PG 状态和统计信息将从 Monitor迁移至 Manager 组件：</p><ul><li>Kraken 版本：提供实验性 Manager 支持</li><li>Luminous 版本：完成正式迁移</li></ul><p>这是 Ceph 监控架构的重要分层决策，将 Monitor 从繁重的统计聚合职责中解放出来。</p><p><strong>统一 CI 系统建设</strong><a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">Unified CI Tech Talk</a>) 确立了基于 Jenkins + Docker + Kubernetes 的新构建体系，引入 Nexus/Artifactory 做依赖管理，Ansible 做资源管理，解决原有构建耗时数天、可扩展性差的问题。</p><p><strong>Messenger 2 计划启动</strong> 9月月会中提及 Messenger 2 计划，标志着网络层的下一代重构正式进入议程。</p><p><strong>AutoMake 升级</strong> 构建系统层面完成 AutoMake 升级，属于工程基础设施改善。</p><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><p><strong>开发者月度会议</strong> 本季度举行了两次 Ceph Developer Monthly：</p><ul><li><a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">8月会议</a>)：覆盖 BlueStore、Mantle、RBD 镜像、Manager、EC、DDO、Scrub 等 8 个议题，参与度高</li><li><a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">9月会议</a>)：聚焦 RBD 快照一致性组、Kerberos 认证、SIMD 检测等议题</li></ul><p><strong>Tech Talk 系列</strong></p><ul><li><a href="/VideoSummary/posts/2016/2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATTIC.html">6月 OpenATTIC Tech Talk</a>)：展示第三方存储管理平台与 Ceph 的深度集成，OpenATTIC 团队宣布与 SUSE 开发者联合举办 Hack Week</li><li><a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">8月 Unified CI Tech Talk</a>)：Alfredo Lisa 分享过去一年半构建系统演进经验</li></ul><p><strong>主要贡献者活跃度</strong> 本季度活跃贡献者包括：Alan Samuels（BlueStore）、Michael Silla（CephFS/Mantle）、Jason（RBD）、John（Manager）、Sam（EC）、Marcel（DDO）、David（Scrub）、Sage（RBD 快照）、Basam（SIMD）、Dan（Kerberos）、Alfredo（CI）。</p><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度讨论内容，预计 2016 Q4 将重点推进：</p><ol><li><strong>Kraken 版本发布准备</strong> — Manager 实验性支持、EC 覆写、BlueStore 序列化优化需在 Kraken 窗口内落地</li><li><strong>RBD 功能完善</strong> — 镜像横向扩展第一阶段（活动/被动故障转移）和客户端持久缓存进入可用状态</li><li><strong>Mantle 生产化评估</strong> — 社区反馈收集后决定是否推进 MDS 负载均衡器的生产就绪工作</li><li><strong>DDO C++ 重写</strong> — Python 原型验证后的工程化实现</li><li><strong>Messenger 2 详细设计</strong> — 网络层重构方案细化</li><li><strong>Kerberos 认证实现</strong> — Dan 负责的认证模块开发</li><li><strong>统一 CI 系统上线</strong> — 新构建体系完成部署并与各团队对接</li><li><strong>OpenATTIC Ceph 仪表板</strong> — Hack Week 成果转化为正式功能迭代</li></ol><hr><p><em>报告基于 2016 Q3 共4 篇会议/Tech Talk 材料整理，涵盖时间范围为 2016 年 6 月至 9 月。</em></p><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2016/2016-AUG-03_-_-_Ceph_Developer_Monthly.html">2016-AUG-03 :: Ceph Developer Monthly</a>)</li><li><a href="/VideoSummary/posts/2016/2016-AUG-25_--_Ceph_Tech_Talk_-_Unified_CI.html">2016-AUG-25 -- Ceph Tech Talk: Unified CI</a>)</li><li><a href="/VideoSummary/posts/2016/2016-JUN-23_--_Ceph_Tech_Talks_-_OpenATTIC.html">2016-JUN-23 -- Ceph Tech Talks: OpenATTIC</a>)</li><li><a href="/VideoSummary/posts/2016/2016-SEP-07_-_-_Ceph_Developer_Monthly.html">2016-SEP-07 :: Ceph Developer Monthly</a>)</li></ul>',58)])])}const c=a(t,[["render",h]]);export{u as __pageData,c as default};
